const COUNTRY_ALIAS = {"usa": "United States of America", "us": "United States of America", "united states": "United States of America", "america": "United States of America", "uk": "United Kingdom", "britain": "United Kingdom", "great britain": "United Kingdom", "england": "United Kingdom", "scotland": "United Kingdom", "wales": "United Kingdom", "uae": "United Arab Emirates", "emirates": "United Arab Emirates", "holland": "Netherlands", "burma": "Myanmar", "czech republic": "Czechia", "turkiye": "Turkey", "korea": "South Korea", "ivory coast": "Côte d'Ivoire"};
function findCountries(q) {
  const t = (q || '').trim().toLowerCase();
  if (!t) return [];
  const out = [];
  const add = (n) => { if (n && !out.includes(n)) out.push(n); };
  Object.keys(COUNTRY_ALIAS).forEach((k) => { if (k === t) add(COUNTRY_ALIAS[k]); });
  COUNTRIES.forEach((c) => { if (c[0].toLowerCase().startsWith(t)) add(c[0]); });
  COUNTRIES.forEach((c) => { if (c[0].toLowerCase().includes(t)) add(c[0]); });
  return out.slice(0, 5);
}
function countryInfo(name) { return COUNTRIES.find((c) => c[0] === name) || null; }

