/* [code, symbol, decimals]. Rates come live from a free rates service when the app opens. */
const CURRENCIES = [['GBP', '£', 2], ['USD', '$', 2], ['EUR', '€', 2], ['THB', '฿', 0], ['AUD', 'A$', 2], ['CAD', 'C$', 2], ['NZD', 'NZ$', 2], ['SGD', 'S$', 2], ['MYR', 'RM ', 2], ['VND', '₫', 0], ['IDR', 'Rp ', 0], ['PHP', '₱', 0], ['JPY', '¥', 0], ['KRW', '₩', 0], ['CNY', 'CN¥', 2], ['INR', '₹', 0]];
function fmtMoney(gbp, cur, rates) {
  const c = CURRENCIES.find((x) => x[0] === cur) || CURRENCIES[0];
  const r = cur === 'GBP' ? 1 : (rates && rates[cur]);
  if (!r) return '£' + gbp.toFixed(2);
  if (gbp === 0) return c[1] + '0';
  const v = gbp * r;
  const parts = v.toFixed(c[2]).split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return c[1] + parts.join('.');
}



