const MODES = [['back', 'Backpack'], ['moto', 'Motorbike'], ['truck', 'Overland'], ['bike', 'Cycling'], ['train', 'Train']];
const STRIPS = 60;


/* The Where to? box on Home: type a country and the whole app turns to it */
function WhereBox() {
  const { country, setCountry } = useApp();
  const [q, setQ] = useState('');
  const same = q.trim().toLowerCase() === (country || '').toLowerCase();
  const list = q.trim() && !same ? findCountries(q) : [];
  const pick = (n) => { setCountry(n); setQ(n); Keyboard.dismiss(); };
  return (
    <View style={{ marginTop: 20 }}>
      <View style={styles.whereBox}>
        <SearchIcon />
        <TextInput
          style={styles.whereInput}
          value={q}
          onChangeText={(t) => { setQ(t); if (!t.trim() && country) setCountry(''); }}
          onSubmitEditing={() => { const f = findCountries(q); if (f.length) pick(f[0]); }}
          returnKeyType="search"
          placeholder={T('Where to?')}
          placeholderTextColor="#9FC4D2"
        />
        {!!country && (
          <Pressable onPress={() => { setCountry(''); setQ(''); }} hitSlop={8}>
            <Text style={styles.whereClear}>Clear</Text>
          </Pressable>
        )}
      </View>
      {list.length > 0 && (
        <View style={styles.whereList}>
          {list.map((n) => <Chip key={n} small label={n} onPress={() => pick(n)} />)}
        </View>
      )}
    </View>
  );
}

function ModeLine() {
  const { mode, country } = useApp();
  if (!country) return null;
  return <Text style={styles.modeLine}>{country + ' · ' + MODES[mode][1]}</Text>;
}

