function Bar({ h, ms }) {
  const v = useRef(new Animated.Value(0.6)).current;
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(v, { toValue: 1, duration: ms, useNativeDriver: true }),
      Animated.timing(v, { toValue: 0.55, duration: ms, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  return <Animated.View style={{ width: 4, height: h, borderRadius: 2, backgroundColor: TEAL, transform: [{ scaleY: v }] }} />;
}

