function GuidesScreen() {
  const { height } = useWindowDimensions();
  const [mode, setMode] = useState('talk');
  const [text, setText] = useState('');
  const [kb, setKb] = useState(0);
  const [msgs, setMsgs] = useState(START);
  const [done, setDone] = useState({});
  const { aiSeed } = useApp();
  useEffect(() => {
    if (aiSeed) setMsgs((m) => [...m, { from: 'me', text: aiSeed.me }, { from: 'ai', text: aiSeed.ai }]);
  }, [aiSeed && aiSeed.id]);
  const scroller = useRef(null);
  const ring = Math.max(100, Math.min(142, height * 0.165));

  useEffect(() => {
    const ios = Platform.OS === 'ios';
    const a = Keyboard.addListener(ios ? 'keyboardWillShow' : 'keyboardDidShow', (e) => setKb(e.endCoordinates.height));
    const b = Keyboard.addListener(ios ? 'keyboardWillHide' : 'keyboardDidHide', () => setKb(0));
    return () => { a.remove(); b.remove(); };
  }, []);

  const send = (t) => {
    const q = (t !== undefined ? t : text).trim();
    if (!q) return;
    setMsgs((m) => [...m, { from: 'me', text: q }, { from: 'ai', typing: true }]);
    setText('');
  };

  return (
    <View style={[styles.guideScreen, Platform.OS === 'ios' && kb > 0 && { paddingBottom: Math.max(0, kb - TAB_H) }]}>
      <View style={styles.mapHeader}>
        <Text style={styles.mapTitle}>{T('AI Guide')}</Text>
        <TopRight />
      </View>

      {kb === 0 && (
        <View style={{ alignItems: 'center' }}>
          <View style={styles.seg}>
            {['talk', 'lens'].map((k) => (
              <Pressable key={k} onPress={() => setMode(k)} style={[styles.segItem, mode === k && styles.segOn]}>
                <Text style={[styles.segText, mode === k && { color: '#04202E' }]}>{k === 'talk' ? 'Talk' : 'Lens'}</Text>
              </Pressable>
            ))}
          </View>
          <View style={{ width: ring + 20, height: ring + 20, alignItems: 'center', justifyContent: 'center', marginTop: 10 }}>
            {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => (
              <View key={i} pointerEvents="none" style={{ position: 'absolute', width: ring + 20 + i * 30, height: ring + 20 + i * 30, borderRadius: (ring + 20 + i * 30) / 2, backgroundColor: 'rgba(53,196,212,0.03)' }} />
            ))}
            <View style={[styles.guideRing, { width: ring, height: ring, borderRadius: ring / 2 }]}>
              {mode === 'talk' ? (
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10.4 }}>
                  <View style={{ width: 4, height: 4, borderRadius: 2, backgroundColor: TEAL }} />
                  {WAVE.map((h, i) => <Bar key={i} h={h * (ring / 170)} ms={420 + i * 70} />)}
                </View>
              ) : (
                <View style={{ width: 64, height: 64 }}>
                  <Corner pos="tl" /><Corner pos="tr" /><Corner pos="bl" /><Corner pos="br" />
                </View>
              )}
            </View>
          </View>
          {height >= 700 && <Text style={styles.guideName}>{mode === 'talk' ? 'AI Guide' : 'Smart Lens'}</Text>}
        </View>
      )}

      <ScrollView
        ref={scroller}
        style={{ flex: 1 }}
        contentContainerStyle={{ padding: 20, paddingTop: 14, gap: 12 }}
        onContentSizeChange={() => scroller.current && scroller.current.scrollToEnd && scroller.current.scrollToEnd({ animated: true })}
      >
        {msgs.map((m, i) => m.from === 'me' ? (
          <View key={i} style={{ alignItems: 'flex-end' }}>
            <View style={styles.meBubble}><Text style={styles.meText}>{m.text}</Text></View>
          </View>
        ) : (
          <View key={i} style={styles.aiCard}>
            <Text style={styles.aiLabel}>AI GUIDE</Text>
            {m.typing ? <Text style={styles.dots}>···</Text> : <Text style={styles.aiBody}>{m.text}</Text>}
            {m.actions && (
              <View style={styles.aiActions}>
                {m.actions.map((a, j) => {
                  const k = i + '-' + j, on = j === 0 || done[k];
                  return <Chip key={a} label={done[k] ? 'Added' : a} filled={on} onPress={() => setDone({ ...done, [k]: !done[k] })} />;
                })}
              </View>
            )}
          </View>
        ))}
      </ScrollView>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flexGrow: 0 }} contentContainerStyle={styles.quick}>
        {QUICK.map((q) => (
          <Pressable key={q} onPress={() => send(q)} style={({ pressed }) => [styles.quickChip, pressed && { opacity: 0.75 }]}>
            <Text style={styles.quickText}>{q}</Text>
          </Pressable>
        ))}
      </ScrollView>
      <View style={styles.ask}>
        <TextInput
          style={styles.askInput}
          value={text}
          onChangeText={setText}
          onSubmitEditing={() => send()}
          returnKeyType="send"
          placeholder="Ask me anything…"
          placeholderTextColor="#7FA3B4"
        />
      </View>
    </View>
  );
}

