function MapScreen({ goTo }) {
  const { width, height } = useWindowDimensions();
  const { toggleSaved, isSaved, addStop, planHas, flyReq } = useApp();
  const [areaH, setAreaH] = useState(0);
  const [q, setQ] = useState('');
  const [open, setOpen] = useState(height >= 720);
  const [focus, setFocus] = useState(null);
  const [mapOn, setMapOn] = useState(false);
  const web = useRef(null);
  const dia = Math.floor(Math.min(width * 0.88, areaH - 98));
  const pend = useRef(null);
  const inject = () => {
    const p = pend.current;
    if (p && web.current && web.current.injectJavaScript) web.current.injectJavaScript('window.flyTo&&window.flyTo(' + p[0] + ',' + p[1] + ',' + p[2] + ');true;');
  };
  const flyTo = (name, lon, lat, z) => {
    setMapOn(false);
    setFocus({ name, lon, lat });
    pend.current = [lon, lat, z];
    inject();
    [700, 1800].forEach((ms) => setTimeout(inject, ms));
  };
  useEffect(() => { if (areaH > 0 && pend.current) [900, 1900].forEach((ms) => setTimeout(inject, ms)); }, [areaH > 0]);
  useEffect(() => { if (flyReq) flyTo(flyReq.name, flyReq.lon, flyReq.lat, flyReq.z); }, [flyReq && flyReq.id]);
  const doSearch = () => {
    const t = q.trim().toLowerCase();
    if (!t) return;
    const c = findCountries(q)[0];
    const ci = c ? countryInfo(c) : null;
    if (ci) { flyTo(ci[0], ci[1], ci[2], ci[3]); return; }
    const city = CITIES.find((x) => x[0].toLowerCase().includes(t));
    if (city) flyTo(city[0], city[1], city[2], 4);
  };

  const onMsg = (e) => {
    try {
      const m = JSON.parse(e.nativeEvent.data);
      if (m.t === 'city') setFocus({ name: m.name, lon: m.lon, lat: m.lat });
      else if (m.t === 'view') {
        if (m.z >= 2.2) setFocus({ name: m.city || '', lon: m.lon, lat: m.lat });
        else if (m.z < 1.3) setFocus(null);
      } else if (m.t === 'open') { setFocus({ name: m.city || '', lon: m.lon, lat: m.lat }); setMapOn(true); }
    } catch (err) { /* ignore */ }
  };
  const backToGlobe = () => {
    setMapOn(false);
    if (web.current && web.current.injectJavaScript) web.current.injectJavaScript('window.resetView&&window.resetView(2);true;');
  };
  const place = focus ? focus.name : 'Bangkok';
  const showOpen = !mapOn && areaH > 0 && (focus || !WebView);

  return (
    <View style={styles.mapScreen}>
      <View style={styles.mapHeader}>
        <View>
          <Text style={styles.mapTitle}>{T('Map')}</Text>
          <ModeLine />
        </View>
        <TopRight />
      </View>

      <View style={{ flex: 1 }} onLayout={(e) => setAreaH(e.nativeEvent.layout.height)}>
        {areaH > 0 && (WebView ? (
          <WebView
            ref={web}
            originWhitelist={['*']}
            source={{ html: GLOBE_HTML }}
            onMessage={onMsg}
            style={{ flex: 1, backgroundColor: MAPBG }}
            containerStyle={{ backgroundColor: MAPBG }}
            scrollEnabled={false}
            bounces={false}
            overScrollMode="never"
            showsVerticalScrollIndicator={false}
            showsHorizontalScrollIndicator={false}
          />
        ) : (
          <StillGlobe width={width} dia={dia} />
        ))}
        {dia > 0 && !mapOn && (
          <View pointerEvents="box-none" style={[styles.aiRing, { top: dia - 14 }]}>
            <Pressable onPress={() => goTo('Guides')} style={styles.aiBtn}>
              <Sparkle />
              <Text style={styles.aiText}>AI GUIDE</Text>
            </Pressable>
          </View>
        )}
        {showOpen && (
          <View pointerEvents="box-none" style={styles.openMapWrap}>
            <Pressable onPress={() => setMapOn(true)} style={styles.openMap}>
              <Text style={styles.openMapText}>{place ? 'Open map · ' + place : 'Open map'}</Text>
            </Pressable>
          </View>
        )}
        {mapOn && <RealMap focus={focus} onBack={backToGlobe} />}
      </View>

      <View style={styles.search}>
        <SearchIcon />
        <TextInput style={styles.searchInput} value={q} onChangeText={setQ} onSubmitEditing={doSearch} returnKeyType="search" placeholder="Search places, gems and routes" placeholderTextColor="#9FC4D2" />
        <View style={styles.filterBtn}><FilterIcon /></View>
      </View>

      <View style={styles.sheet}>
        <View style={styles.handle} />
        <Pressable style={[styles.sheetTitleRow, !open && { marginBottom: 2 }]} onPress={() => setOpen(!open)}>
          <Text style={styles.sheetTitle}>RECOMMENDED NEARBY</Text>
          <Chevron up={!open} />
        </Pressable>
        {open && (
          <View style={styles.listing}>
            <View style={styles.listingTop}>
              <View style={styles.thumb} />
              <View>
                <Text style={styles.example}>EXAMPLE LISTING</Text>
                <Text style={styles.listName}>Hidden waterfall</Text>
              </View>
            </View>
            <View style={styles.chips}>
              <Chip label={isSaved('Hidden waterfall', 'Map') ? 'Saved' : 'Save'} filled onPress={() => toggleSaved({ title: 'Hidden waterfall', from: 'Map' })} />
              <Chip label={planHas('Hidden waterfall') ? 'Added' : 'Add to itinerary'} filled={planHas('Hidden waterfall')} onPress={() => addStop('Hidden waterfall')} />
              <Chip label="Book" onPress={() => goTo('Book')} />
            </View>
          </View>
        )}
      </View>
    </View>
  );
}

