const ITIN_MODES = [['back', 'Backpack'], ['moto', 'Motorbike'], ['truck', 'Overland'], ['bike', 'Cycling'], ['train', 'Transit']];
const TRIPS = [
  { img: ITIN_A, title: 'Chiang Mai to Pai loop', meta: '3 days · Motorbike · Adventure', by: 'OFF ROUTE', badge: 'Official', country: 'Thailand', style: 'Adventure', days: 3, level: 'Explorer' },
  { img: ITIN_B, title: 'Northern temples ride', meta: '5 days · Motorbike · Cultural', by: 'Mali', badge: 'Pathfinder', country: 'Thailand', style: 'Cultural', days: 5, level: 'Adventurer' },
];
