/* ---------- Profile screen (from the Profile design) ---------- */
const PF_TABS = ['Posts', 'Itineraries', 'Blogs', 'Saved'];
const PF_TILES = [PF_A, ITIN_A, BK_B, BK_C, PF_B, BK_A];
const AVATAR_STRIPS = (function () {
  const n = 28;
  const rows = [];
  for (let i = 0; i < n; i++) {
    const k = i / (n - 1);
    const r = Math.round(52 + (22 - 52) * k);
    const g = Math.round(180 + (104 - 180) * k);
    const b = Math.round(196 + (128 - 196) * k);
    rows.push(<View key={i} style={{ flex: 1, backgroundColor: 'rgb(' + r + ',' + g + ',' + b + ')' }} />);
  }
  return rows;
})();

/* Links: the user adds only the platforms they use. A bare username is turned into that platform's address. */
const PLATFORMS = ['TikTok', 'YouTube', 'Instagram', 'Facebook', 'X', 'Threads', 'LinkedIn', 'Pinterest', 'Snapchat', 'Twitch', 'Reddit', 'Telegram', 'Website', 'Blog', 'Other'];
const LINK_BASE = {
  TikTok: 'https://www.tiktok.com/@', YouTube: 'https://www.youtube.com/@', Instagram: 'https://www.instagram.com/', Facebook: 'https://www.facebook.com/',
  X: 'https://x.com/', Threads: 'https://www.threads.com/@', LinkedIn: 'https://www.linkedin.com/in/', Pinterest: 'https://www.pinterest.com/',
  Snapchat: 'https://www.snapchat.com/add/', Twitch: 'https://www.twitch.tv/', Reddit: 'https://www.reddit.com/user/', Telegram: 'https://t.me/',
};
function linkUrl(l) {
  const v = (l.value || '').trim();
  if (!v) return '';
  const base = LINK_BASE[l.platform];
  const full = /^https?:\/\//i.test(v);
  const isAddr = full || /^www\./i.test(v) || v.indexOf('/') >= 0 || !base;
  if (isAddr) return full ? v : 'https://' + v;
  return base + v.replace(/^@/, '');
}
function linkLabel(l) { return l.platform === 'Other' ? (l.label || 'Link') : l.platform; }
function openUrl(u) { if (u) Linking.openURL(u).catch(() => {}); }
function postUrl(v) { return /^https?:\/\//i.test(v) ? v : 'https://' + v; }
const countStops = (it) => it.stops.reduce((n, d) => n + d.length, 0);

