/* ---------- Logins: Supabase client and the sign-in screen ---------- */
const LOGIN_ON = !!(SUPABASE_URL && SUPABASE_KEY);
let AUTH_ERR = '';
function makeClient() {
  if (!LOGIN_ON) return null;
  try {
    try { require('react-native-url-polyfill/auto'); } catch (e) { /* optional */ }
    const { createClient } = require('@supabase/supabase-js');
    const mem = {};
    const storage = {
      getItem: async (k) => (k in mem ? mem[k] : null),
      setItem: async (k, v) => { mem[k] = v; },
      removeItem: async (k) => { delete mem[k]; },
    };
    return createClient(SUPABASE_URL, SUPABASE_KEY, {
      auth: { storage, autoRefreshToken: true, persistSession: true, detectSessionInUrl: false },
    });
  } catch (e) {
    AUTH_ERR = String((e && e.message) || e);
    return null;
  }
}
const supabase = makeClient();

function AuthScreen({ client }) {
  const [mode, setMode] = useState('in');
  const [email, setEmail] = useState('');
  const [pw, setPw] = useState('');
  const [msg, setMsg] = useState('');
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    if (!client || busy) return;
    const em = email.trim();
    if (!em || !pw) { setMsg('Add your email and password to continue.'); return; }
    setBusy(true);
    setMsg('');
    try {
      if (mode === 'in') {
        const { error } = await client.auth.signInWithPassword({ email: em, password: pw });
        if (error) setMsg('Check your email and password and try again.');
      } else {
        const { data, error } = await client.auth.signUp({ email: em, password: pw });
        if (error) setMsg(error.message);
        else if (!data.session) { setMsg('Check your email to confirm your account, then sign in.'); setMode('in'); }
      }
    } catch (e) {
      setMsg('Check your connection and try again.');
    }
    setBusy(false);
  };

  return (
    <View style={{ flex: 1, backgroundColor: DEEP }}>
      <StatusBar barStyle="light-content" backgroundColor={DEEP} />
      <Image source={{ uri: BG_IMG }} style={[StyleSheet.absoluteFill, { opacity: 0.8, resizeMode: 'cover', width: '100%', height: '100%' }]} />
      <View pointerEvents="none" style={StyleSheet.absoluteFill}>
        {Array.from({ length: 40 }, (_, i) => <View key={i} style={{ flex: 1, backgroundColor: 'rgba(6,20,31,' + (0.55 + 0.35 * Math.min(1, i / 20)).toFixed(3) + ')' }} />)}
      </View>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ flexGrow: 1, justifyContent: 'center', paddingHorizontal: 26, paddingVertical: 40 }}>
          <View style={{ alignItems: 'center' }}>
            <Image source={{ uri: SOC_IC.compass }} style={{ width: 54, height: 54 }} />
            <Text style={styles.authBrand}>OFF ROUTE</Text>
            <Text style={styles.authTag}>EXPLORE OFF ROUTE.</Text>
          </View>

          {client ? (
            <View style={{ marginTop: 30 }}>
              <View style={[styles.seg, { alignSelf: 'center', marginTop: 0 }]}>
                {[['in', 'Sign in'], ['up', 'Create account']].map(([k, label]) => (
                  <Pressable key={k} onPress={() => { setMode(k); setMsg(''); }} style={[styles.segItem, mode === k && styles.segOn]}>
                    <Text style={[styles.segText, mode === k && { color: '#04202E' }]}>{label}</Text>
                  </Pressable>
                ))}
              </View>
              <TextInput
                style={styles.authInput}
                value={email}
                onChangeText={setEmail}
                placeholder="Email"
                placeholderTextColor="#7FA3B4"
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="email-address"
              />
              <TextInput
                style={styles.authInput}
                value={pw}
                onChangeText={setPw}
                placeholder="Password"
                placeholderTextColor="#7FA3B4"
                autoCapitalize="none"
                autoCorrect={false}
                secureTextEntry
                onSubmitEditing={submit}
              />
              <Text style={styles.authMsg}>{msg}</Text>
              <Pressable onPress={submit} style={({ pressed }) => [styles.authBtn, (pressed || busy) && { opacity: 0.7 }]}>
                <Text style={styles.authBtnText}>{mode === 'in' ? 'Sign in' : 'Create account'}</Text>
              </Pressable>
            </View>
          ) : (
            <View style={[styles.aiCard, { marginTop: 30, marginRight: 0 }]}>
              <Text style={styles.aiLabel}>ONE STEP LEFT</Text>
              <Text style={styles.aiBody}>In Snack, tap Add dependency on the supabase lines, then reload the app.</Text>
              {!!AUTH_ERR && <Text style={[styles.authMsg, { color: '#7FA3B4', marginTop: 8 }]}>{AUTH_ERR}</Text>}
            </View>
          )}
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

/* ---------- Navigation: Map, Itineraries, Home (raised, centre), Bookings, Social. Profile opens from your avatar. ---------- */
const TABS = [['Map', 'Map'], ['Itineraries', 'Itineraries'], ['Home', 'Home'], ['Book', 'Bookings'], ['Social', 'Social']];
const SUBS = ['Pro', 'NewPost', 'EditProfile', 'Settings', 'Web'];
const BASE_PAGES = [['Home', Home], ['Itineraries', ItinerariesScreen], ['Book', BookScreen], ['Social', SocialScreen], ['Profile', ProfileScreen]];
const DEFAULT_BIO = 'Riding and overlanding across Southeast Asia. Itineraries and honest tips from the road.';

export default function App() {
  const [page, setPage] = useState('Home');
  const stack = useRef([]);
  const [mode, setMode] = useState(1);
  const [plan, setPlan] = useState(START_PLAN);
  const [savedItins, setSavedItins] = useState([]);
  const [saved, setSaved] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [posts, setPosts] = useState([]);
  const [blogs, setBlogs] = useState([]);
  const [profile, setProfile] = useState({ name: '', bio: DEFAULT_BIO, links: [], isPublic: true });
  const [seed, setSeed] = useState({});
  const [guide, setGuide] = useState(0);
  const [pfTab, setPfTab] = useState(0);
  const [aiSeed, setAiSeed] = useState(null);
  const [country, setCountryRaw] = useState('');
  const [flyReq, setFlyReq] = useState(null);
  const [web, setWeb] = useState(null);
  const [lang, setLang] = useState('en');
  const [currency, setCurrency] = useState('GBP');
  const [rates, setRates] = useState(null);
  const [tier, setTier] = useState('free');
  const [popup, setPopup] = useState(false);
  const [popSeen, setPopSeen] = useState(false);
  LANG = lang;
  useEffect(() => {
    let off = false;
    try {
      fetch('https://open.er-api.com/v6/latest/GBP').then((r) => r.json()).then((j) => { if (!off && j && j.rates) setRates(j.rates); }).catch(() => {});
    } catch (e) { /* offline: prices stay in pounds */ }
    return () => { off = true; };
  }, []);
  useEffect(() => {
    if (tier !== 'free' || popSeen || !['Home', 'Social', 'Map', 'Profile'].includes(page)) return undefined;
    const t = setTimeout(() => { setPopup(true); setPopSeen(true); }, POPUP_DELAY);
    return () => clearTimeout(t);
  }, [page, tier, popSeen]);
  const [session, setSession] = useState(null);
  const [ready, setReady] = useState(!supabase);
  useEffect(() => {
    if (!supabase) return undefined;
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setReady(true); }).catch(() => setReady(true));
    const { data } = supabase.auth.onAuthStateChange((_event, s) => setSession(s));
    return () => data.subscription.unsubscribe();
  }, []);

  /* One place for every move. Smart Lens and the AI Guide open from Home, so Home stays lit. Pro, New post, Edit profile, Settings and Guide have a Back. */
  const go = (p, o) => {
    if (o) {
      if (o.guide !== undefined) setGuide(o.guide);
      if (o.pfTab !== undefined) setPfTab(o.pfTab);
      if (o.web !== undefined) setWeb(o.web);
    }
    if (p === 'NewPost') setSeed((o && o.seed) || {});
    if (p === 'Back') { setPage(stack.current.pop() || 'Home'); return; }
    if (SUBS.includes(p)) stack.current.push(page); else stack.current = [];
    setPage(p);
  };

  if (LOGIN_ON && !ready) return <View style={{ flex: 1, backgroundColor: DEEP }} />;
  if (LOGIN_ON && !session) return <AuthScreen client={supabase} />;
  const user = session ? session.user : null;
  const signOut = () => { if (supabase) supabase.auth.signOut(); };

  const same = (a, b) => a.title === b.title && a.from === b.from;
  /* Opens the AI Guide with your trip (or one day of it) already in the chat */
  const askAI = (d, opt) => {
    const names = (a) => a.map((x) => x.title).join(', ');
    let me, ai;
    if (d === undefined || d === null) {
      const filled = plan.stops.slice(0, plan.days).map((a, i) => (a.length ? 'Day ' + (i + 1) + ': ' + names(a) + '.' : null)).filter(Boolean);
      const st = opt && opt.style ? ' Style: ' + opt.style + '.' : '';
      me = 'Help me plan my ' + plan.days + '-day ' + plan.city + ' trip.' + st;
      ai = 'Your ' + plan.city + ' trip is ' + plan.days + ' days.' + st + ' ' + (filled.length ? filled.join(' ') : 'No stops are added yet.') + ' Tell me what you would like and we will plan it together.';
    } else {
      const a = plan.stops[d] || [];
      me = 'Help me plan Day ' + (d + 1) + ' of my ' + plan.city + ' trip.';
      ai = 'Day ' + (d + 1) + ' of ' + plan.days + ' in ' + plan.city + ': ' + (a.length ? names(a) + '.' : 'no stops yet.') + ' Tell me what you would like to do and we will plan it together.';
    }
    setAiSeed({ id: Date.now(), me, ai });
    go('Guides');
  };
  const setCountry = (name) => {
    setCountryRaw(name);
    if (!name) return;
    const c = countryInfo(name);
    if (c) setFlyReq({ id: Date.now(), name: c[0], lon: c[1], lat: c[2], z: c[3] });
    setPlan((p) => (p.id ? p : { ...p, city: name }));
  };
  const ctx = {
    country, setCountry, flyReq, web,
    lang, setLang, currency, setCurrency, rates, tier, setTier, money: (g) => fmtMoney(g, currency, rates),
    go, mode, setMode, plan, setPlan, profile, setProfile, posts, blogs, bookings, saved, savedItins, seed, guide, pfTab, setPfTab, aiSeed, askAI,
    isSaved: (title, from) => saved.some((s) => same(s, { title, from })),
    toggleSaved: (it) => setSaved((l) => (l.some((s) => same(s, it)) ? l.filter((s) => !same(s, it)) : [it, ...l])),
    planHas: (title) => plan.stops.some((d) => d.some((s) => s.title === title)),
    addStop: (title) => setPlan((p) => (p.stops.some((d) => d.some((s) => s.title === title)) ? p : { ...p, stops: p.stops.map((a, i) => (i === 0 ? [...a, { title, sub: '' }] : a)) })),
    addBooking: (l) => setBookings((b) => (b.some((x) => x.title === l.title) ? b : [l, ...b])),
    addPost: (p) => { const e = { ...p, id: String(Date.now()), status: 'Pending review' }; if (p.kind === 'blog') setBlogs((b) => [e, ...b]); else setPosts((b) => [e, ...b]); },
    saveItin: () => {
      const id = plan.id || 'it' + Date.now();
      const entry = { id, city: plan.city, days: plan.days, stops: plan.stops.slice(0, plan.days), mode };
      setPlan({ ...plan, id });
      setSavedItins((l) => (l.some((x) => x.id === id) ? l.map((x) => (x.id === id ? entry : x)) : [entry, ...l]));
    },
    openItin: (it) => { setPlan({ id: it.id, city: it.city, days: it.days, stops: it.stops }); go('Itineraries'); },
  };

  const lit = page === 'Lens' || page === 'Guides' ? 'Home' : page;
  return (
    <AppCtx.Provider value={ctx}>
      <View style={{ flex: 1, backgroundColor: DEEP }}>
        <StatusBar barStyle="light-content" backgroundColor={MAPBG} />
        <View style={{ flex: 1 }}>
          <View style={[styles.fill, page !== 'Map' && styles.hide]}><MapScreen goTo={go} /></View>
          {BASE_PAGES.map(([id, Page]) => (
            <View key={id} style={[styles.fill, page !== id && styles.hide]}><Page goTo={go} user={user} onSignOut={signOut} /></View>
          ))}
          <View style={[styles.fill, page !== 'Lens' && styles.hide]}><LensScreen goTo={go} active={page === 'Lens'} /></View>
          <View style={[styles.fill, page !== 'Guides' && styles.hide]}><GuidesScreen /></View>
          {page === 'Pro' && <View style={styles.fill}><ProScreen /></View>}
          {page === 'Web' && <View style={styles.fill}><WebScreen /></View>}
          {page === 'NewPost' && <View style={styles.fill}><NewPostScreen /></View>}
          {page === 'EditProfile' && <View style={styles.fill}><EditProfileScreen /></View>}
          {page === 'Settings' && <View style={styles.fill}><SettingsScreen user={user} onSignOut={signOut} /></View>}
        </View>
        <View style={styles.tabBar}>
          {TABS.map(([id, label]) => {
            const on = lit === id;
            return (
              <Pressable key={id} onPress={() => go(id)} style={styles.tabItem}>
                {id === 'Home' ? (
                  <Image source={{ uri: SOC_IC.compass }} style={[styles.tabCompass, !on && { opacity: 0.55 }]} />
                ) : (
                  <View style={[styles.tabIcon, on && styles.tabIconOn]} />
                )}
                <Text style={[styles.tabLabel, on && { color: TEAL }]}>{T(label)}</Text>
              </Pressable>
            );
          })}
        </View>
        {page === 'Social' && <View pointerEvents="none" style={styles.socFrame} />}
        {popup && (
          <View style={styles.popDim}>
            <View style={styles.popCard}>
              <Text style={styles.aiLabel}>OFF ROUTE PRO</Text>
              <Text style={styles.popTitle}>Upgrade to Pro</Text>
              <Text style={styles.proNote}>{T('Try Pro free for 7 days')}</Text>
              <View style={{ flexDirection: 'row', gap: 10, marginTop: 14 }}>
                <Chip filled label="See Pro" onPress={() => { setPopup(false); go('Pro'); }} />
                <Chip label="Not now" onPress={() => setPopup(false)} />
              </View>
            </View>
          </View>
        )}
      </View>
    </AppCtx.Provider>
  );
}

